def first_last(a: list[int], target: int) -> tuple[int, int]:
    def bound(pred) -> int:
        lo, hi, ans = 0, len(a) - 1, len(a)
        while lo <= hi:
            mid = lo + (hi - lo) // 2
            if pred(a[mid]):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

    first = bound(lambda v: v >= target)
    if first == len(a) or a[first] != target:
        return (-1, -1)
    last = bound(lambda v: v > target) - 1
    return (first, last)
